<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edit Test</title><style>body{margin:0;background:#f1f7fb;color:#12304c;font-family:Arial}.wrap{max-width:750px;margin:42px auto;padding:0 20px}.card{background:#fff;border:1px solid #dce9f0;border-radius:14px;padding:25px}.back{color:#2476c7;text-decoration:none;font-weight:bold}.field{margin:15px 0}.field label{display:block;font-size:13px;font-weight:bold;margin-bottom:6px}input,textarea,select{box-sizing:border-box;width:100%;padding:11px;border:1px solid #cbdce7;border-radius:8px;font:inherit}textarea{min-height:110px}button{background:#16b9a7;border:0;border-radius:8px;color:#fff;font-weight:bold;padding:12px 18px}.preview{display:block;width:200px;height:130px;object-fit:cover;border-radius:8px;margin-top:8px}</style></head><body><main class="wrap"><p><a class="back" href="{{ route('admin.tests.index') }}">← Tests</a></p><form class="card" method="post" action="{{ route('admin.tests.update',$test->id) }}" enctype="multipart/form-data">@csrf<h1>Edit Test</h1><div class="field"><label>Assign to service</label><select name="service_id">@foreach($services as $service)<option value="{{ $service->id }}" {{ $service->id == $test->service_id ? 'selected' : '' }}>{{ $service->name }}</option>@endforeach</select></div><div class="field"><label>Test name</label><input name="name" value="{{ $test->name }}" required></div><div class="field"><label>Card heading</label><input name="heading" value="{{ $test->heading }}"></div><div class="field"><label>Description</label><textarea name="description">{{ $test->description }}</textarea></div><div class="field"><label>Test photo</label><input type="file" name="image" accept="image/png,image/jpeg,image/webp">@if($test->image_path)<img class="preview" src="{{ asset('storage/'.$test->image_path) }}" alt="Current photo">@endif</div><button>Save changes</button></form></main></body></html>
